CREATE OR REPLACE FUNCTION public.accept_coachingos_staff_invitation(_token_hash text)
 RETURNS TABLE(institute_id uuid, role text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
                                                                                                                                        declare
                                                                                                                                          invite_row public.institute_staff_invitations%rowtype;
                                                                                                                                            account_row record;
                                                                                                                                            begin
                                                                                                                                              if (select auth.uid()) is null then
                                                                                                                                                  raise exception 'Sign in before accepting an invitation'
                                                                                                                                                        using errcode = '42501';
                                                                                                                                                          end if;

                                                                                                                                                            if coalesce(_token_hash,'') !~ '^[0-9a-f]{64}$' then
                                                                                                                                                                raise exception 'Invalid invitation link' using errcode = '22023';
                                                                                                                                                                  end if;

                                                                                                                                                                    select i.* into invite_row
                                                                                                                                                                      from public.institute_staff_invitations i
                                                                                                                                                                        where i.token_hash = _token_hash
                                                                                                                                                                          for update;

                                                                                                                                                                            if not found then
                                                                                                                                                                                raise exception 'Invitation not found or invalid';
                                                                                                                                                                                  end if;

                                                                                                                                                                                    if invite_row.status <> 'pending' then
                                                                                                                                                                                        raise exception 'This invitation is no longer pending';
                                                                                                                                                                                          end if;

                                                                                                                                                                                            if invite_row.expires_at <= now() then
                                                                                                                                                                                                raise exception 'This invitation has expired';
                                                                                                                                                                                                  end if;

                                                                                                                                                                                                    select u.email,u.phone,u.email_confirmed_at,u.phone_confirmed_at
                                                                                                                                                                                                        into account_row
                                                                                                                                                                                                          from auth.users u
                                                                                                                                                                                                            where u.id = (select auth.uid());

                                                                                                                                                                                                              if invite_row.email is not null and (
                                                                                                                                                                                                                  account_row.email_confirmed_at is null
                                                                                                                                                                                                                      or lower(coalesce(account_row.email,'')) <> lower(invite_row.email)
                                                                                                                                                                                                                        ) then
                                                                                                                                                                                                                            raise exception 'Sign in with the verified email address this invitation was sent to'
                                                                                                                                                                                                                                  using errcode = '42501';
                                                                                                                                                                                                                                    end if;

                                                                                                                                                                                                                                      if invite_row.phone is not null and (
                                                                                                                                                                                                                                          account_row.phone_confirmed_at is null
                                                                                                                                                                                                                                              or coalesce(account_row.phone,'') <> invite_row.phone
                                                                                                                                                                                                                                                ) then
                                                                                                                                                                                                                                                    raise exception 'Sign in with the verified phone number this invitation was sent to'
                                                                                                                                                                                                                                                          using errcode = '42501';
                                                                                                                                                                                                                                                            end if;

                                                                                                                                                                                                                                                              insert into public.institute_members(institute_id,user_id,role)
                                                                                                                                                                                                                                                                values(invite_row.institute_id,(select auth.uid()),invite_row.role)
                                                                                                                                                                                                                                                                  on conflict (institute_id,user_id) do nothing;

                                                                                                                                                                                                                                                                    if not found then
                                                                                                                                                                                                                                                                        raise exception 'This account is already a member of the institute';
                                                                                                                                                                                                                                                                          end if;

                                                                                                                                                                                                                                                                            update public.institute_staff_invitations
                                                                                                                                                                                                                                                                              set status='accepted',
                                                                                                                                                                                                                                                                                    accepted_by=(select auth.uid()),
                                                                                                                                                                                                                                                                                          accepted_at=now()
                                                                                                                                                                                                                                                                                            where id=invite_row.id;

                                                                                                                                                                                                                                                                                              return query select invite_row.institute_id,invite_row.role;
                                                                                                                                                                                                                                                                                              end;
                                                                                                                                                                                                                                                                                              $function$

CREATE OR REPLACE FUNCTION public.admin_add_coachingos_member(_institute_id uuid, _email text, _role text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
                                                                                                                                                                                                                                     declare
                                                                                                                                                                                                                                       caller_role text;
                                                                                                                                                                                                                                         target_user_id uuid;
                                                                                                                                                                                                                                           new_role text := lower(trim(_role));
                                                                                                                                                                                                                                           begin
                                                                                                                                                                                                                                             select m.role into caller_role
                                                                                                                                                                                                                                               from public.institute_members m
                                                                                                                                                                                                                                                 where m.institute_id = _institute_id and m.user_id = (select auth.uid());

                                                                                                                                                                                                                                                   if coalesce(caller_role,'') not in ('owner','admin') then
                                                                                                                                                                                                                                                       raise exception 'Only institute owner or admin can add staff'
                                                                                                                                                                                                                                                             using errcode = '42501';
                                                                                                                                                                                                                                                               end if;
                                                                                                                                                                                                                                                                 if new_role not in ('admin','manager','teacher','accountant','receptionist','staff') then
                                                                                                                                                                                                                                                                     raise exception 'Invalid staff role';
                                                                                                                                                                                                                                                                       end if;
                                                                                                                                                                                                                                                                         if caller_role = 'admin' and new_role = 'admin' then
                                                                                                                                                                                                                                                                             raise exception 'Only the owner can appoint another admin'
                                                                                                                                                                                                                                                                                   using errcode = '42501';
                                                                                                                                                                                                                                                                                     end if;
                                                                                                                                                                                                                                                                                       if coalesce(length(trim(_email)),0) < 5 then
                                                                                                                                                                                                                                                                                           raise exception 'Enter a valid registered account email';
                                                                                                                                                                                                                                                                                             end if;

                                                                                                                                                                                                                                                                                               select u.id into target_user_id
                                                                                                                                                                                                                                                                                                 from auth.users u
                                                                                                                                                                                                                                                                                                   where lower(u.email) = lower(trim(_email))
                                                                                                                                                                                                                                                                                                     limit 1;

                                                                                                                                                                                                                                                                                                       if target_user_id is null then
                                                                                                                                                                                                                                                                                                           raise exception 'No account found for this email. The person must sign up first.';
                                                                                                                                                                                                                                                                                                             end if;
                                                                                                                                                                                                                                                                                                               if exists (
                                                                                                                                                                                                                                                                                                                   select 1 from public.institute_members m
                                                                                                                                                                                                                                                                                                                       where m.institute_id = _institute_id and m.user_id = target_user_id
                                                                                                                                                                                                                                                                                                                         ) then
                                                                                                                                                                                                                                                                                                                             raise exception 'This user is already a member of the institute';
                                                                                                                                                                                                                                                                                                                               end if;

                                                                                                                                                                                                                                                                                                                                 insert into public.institute_members(institute_id,user_id,role)
                                                                                                                                                                                                                                                                                                                                   values (_institute_id,target_user_id,new_role);

                                                                                                                                                                                                                                                                                                                                     return target_user_id;
                                                                                                                                                                                                                                                                                                                                     end;
                                                                                                                                                                                                                                                                                                                                     $function$

CREATE OR REPLACE FUNCTION public.admin_add_coachingos_member_by_contact(_institute_id uuid, _email text, _phone text, _role text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
                          declare
                            caller_role text;
                              target_user_id uuid;
                                new_role text := lower(trim(_role));
                                  email_value text := nullif(lower(trim(coalesce(_email, ''))), '');
                                    phone_value text := nullif(trim(coalesce(_phone, '')), '');
                                    begin
                                      select m.role into caller_role from public.institute_members m
                                        where m.institute_id = _institute_id and m.user_id = (select auth.uid());
                                          if coalesce(caller_role, '') not in ('owner', 'admin') then
                                              raise exception 'Only institute owner or admin can add staff' using errcode = '42501';
                                                end if;
                                                  if new_role not in ('admin','manager','teacher','accountant','receptionist','staff') then
                                                      raise exception 'Invalid staff role';
                                                        end if;
                                                          if caller_role = 'admin' and new_role = 'admin' then
                                                              raise exception 'Only the owner can appoint another admin' using errcode = '42501';
                                                                end if;
                                                                  if email_value is null and phone_value is null then raise exception 'Enter an email address or phone number'; end if;
                                                                    if email_value is not null and (position('@' in email_value) < 2 or position('.' in split_part(email_value, '@', 2)) < 2) then
                                                                        raise exception 'Enter a valid email address';
                                                                          end if;
                                                                            if phone_value is not null and phone_value !~ '^[+][1-9][0-9]{7,14}$' then
                                                                                raise exception 'Use international phone format, for example +8801XXXXXXXXX';
                                                                                  end if;
                                                                                    select u.id into target_user_id from auth.users u
                                                                                      where (email_value is null or (lower(u.email) = email_value and u.email_confirmed_at is not null))
                                                                                          and (phone_value is null or (u.phone = phone_value and u.phone_confirmed_at is not null))
                                                                                            limit 1;
                                                                                              if target_user_id is null then raise exception 'No registered account matches the supplied verified contact details'; end if;
                                                                                                if exists (select 1 from public.institute_members m where m.institute_id = _institute_id and m.user_id = target_user_id) then
                                                                                                    raise exception 'This user is already a member of the institute';
                                                                                                      end if;
                                                                                                        insert into public.institute_members(institute_id, user_id, role) values (_institute_id, target_user_id, new_role);
                                                                                                          return target_user_id;
                                                                                                          end;
                                                                                                          $function$

CREATE OR REPLACE FUNCTION public.admin_assign_coachingos_subscription(_institute_id uuid, _plan_id text, _status text, _trial_days integer DEFAULT 14)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
        declare
          period_start timestamptz := now();
            period_end timestamptz;
              trial_end timestamptz;
              begin
                if not exists (
                    select 1 from public.platform_admins p
                        where p.user_id = (select auth.uid())
                          ) then
                              raise exception 'Platform Super Admin access required'
                                    using errcode = '42501';
                                      end if;

                                        if _status not in ('trial','active','past_due','cancelled','suspended') then
                                            raise exception 'Invalid subscription status';
                                              end if;
                                                if _trial_days is null or _trial_days < 1 or _trial_days > 365 then
                                                    raise exception 'Trial days must be between 1 and 365';
                                                      end if;
                                                        if not exists (select 1 from public.institutes i where i.id = _institute_id) then
                                                            raise exception 'Institute not found';
                                                              end if;
                                                                if not exists (
                                                                    select 1 from public.subscription_plans p
                                                                        where p.id = lower(trim(_plan_id)) and p.is_active = true
                                                                          ) then
                                                                              raise exception 'Choose an active subscription plan';
                                                                                end if;

                                                                                  if _status = 'trial' then
                                                                                      trial_end := period_start + make_interval(days => _trial_days);
                                                                                          period_end := trial_end;
                                                                                            elsif _status = 'active' then
                                                                                                period_end := period_start + interval '1 month';
                                                                                                    trial_end := null;
                                                                                                      else
                                                                                                          period_end := null;
                                                                                                              trial_end := null;
                                                                                                                end if;

                                                                                                                  insert into public.institute_subscriptions(
                                                                                                                      institute_id, plan_id, status, billing_cycle,
                                                                                                                          current_period_start, current_period_end, trial_ends_at, updated_at
                                                                                                                            )
                                                                                                                              values (
                                                                                                                                  _institute_id, lower(trim(_plan_id)), _status, 'monthly',
                                                                                                                                      case when _status in ('trial','active') then period_start else null end,
                                                                                                                                          period_end, trial_end, now()
                                                                                                                                            )
                                                                                                                                              on conflict (institute_id) do update
                                                                                                                                                  set plan_id = excluded.plan_id,
                                                                                                                                                          status = excluded.status,
                                                                                                                                                                  billing_cycle = excluded.billing_cycle,
                                                                                                                                                                          current_period_start = excluded.current_period_start,
                                                                                                                                                                                  current_period_end = excluded.current_period_end,
                                                                                                                                                                                          trial_ends_at = excluded.trial_ends_at,
                                                                                                                                                                                                  updated_at = now();

                                                                                                                                                                                                    return true;
                                                                                                                                                                                                    end;
                                                                                                                                                                                                    $function$

CREATE OR REPLACE FUNCTION public.admin_create_coachingos_staff_invitation(_institute_id uuid, _email text, _phone text, _role text, _token_hash text)
 RETURNS TABLE(id uuid, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
          declare
            caller_role text;
              clean_email text;
                clean_phone text;
                begin
                  select m.role into caller_role
                    from public.institute_members m
                      where m.institute_id = _institute_id
                          and m.user_id = (select auth.uid());

                            if coalesce(caller_role,'') not in ('owner','admin') then
                                raise exception 'Only institute owner or admin can create invitations'
                                      using errcode = '42501';
                                        end if;

                                          if _role not in ('admin','manager','teacher','accountant','receptionist','staff') then
                                              raise exception 'Invalid staff role' using errcode = '22023';
                                                end if;

                                                  if _role = 'admin' and caller_role <> 'owner' then
                                                      raise exception 'Only the institute owner can invite an admin'
                                                            using errcode = '42501';
                                                              end if;

                                                                clean_email := nullif(lower(trim(coalesce(_email,''))), '');
                                                                  clean_phone := nullif(trim(coalesce(_phone,'')), '');

                                                                    if clean_email is null and clean_phone is null then
                                                                        raise exception 'Email or phone is required' using errcode = '22023';
                                                                          end if;

                                                                            if clean_email is not null and clean_email !~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
                                                                                raise exception 'Invalid email address' using errcode = '22023';
                                                                                  end if;

                                                                                    if clean_phone is not null and clean_phone !~ '^[+][1-9][0-9]{7,14}$' then
                                                                                        raise exception 'Phone must use E.164 format' using errcode = '22023';
                                                                                          end if;

                                                                                            if coalesce(_token_hash,'') !~ '^[0-9a-f]{64}$' then
                                                                                                raise exception 'Invalid invitation token hash' using errcode = '22023';
                                                                                                  end if;

                                                                                                    return query
                                                                                                      insert into public.institute_staff_invitations(
                                                                                                          institute_id,email,phone,role,token_hash,created_by,expires_at
                                                                                                            )
                                                                                                              values(
                                                                                                                  _institute_id,clean_email,clean_phone,_role,_token_hash,
                                                                                                                      (select auth.uid()),now()+interval '7 days'
                                                                                                                        )
                                                                                                                          returning institute_staff_invitations.id,
                                                                                                                                      institute_staff_invitations.expires_at;
                                                                                                                                      end;
                                                                                                                                      $function$

CREATE OR REPLACE FUNCTION public.admin_link_coachingos_portal_account(_institute_id uuid, _student_record_id uuid, _email text, _relationship text DEFAULT 'parent'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_role text;
  target_user_id uuid;
  link_id uuid;
  rel text := lower(trim(coalesce(_relationship,'parent')));
begin
  select m.role into caller_role
  from public.institute_members m
  where m.institute_id = _institute_id
    and m.user_id = (select auth.uid());

  if coalesce(caller_role,'') not in ('owner','admin','manager') then
    raise exception 'Portal linking requires institute owner, admin or manager'
      using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.institutes i
    where i.id = _institute_id and i.status = 'active'
  ) then
    raise exception 'Institute is not active';
  end if;

  if rel not in ('student','parent','guardian') then
    raise exception 'Invalid portal relationship';
  end if;

  if coalesce(length(trim(_email)),0) < 5 then
    raise exception 'Enter the registered account email';
  end if;

  if not exists (
    select 1 from public.coachingos_records r
    where r.id = _student_record_id
      and r.institute_id = _institute_id
      and r.record_type = 'students'
  ) then
    raise exception 'Student record not found in this institute';
  end if;

  select u.id into target_user_id
  from auth.users u
  where lower(u.email) = lower(trim(_email))
    and u.email_confirmed_at is not null
  limit 1;

  if target_user_id is null then
    raise exception 'No verified account found for this email. The user must sign up and verify email first.';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(_institute_id::text || ':' || target_user_id::text, 0)
  );

  if rel = 'student' and exists (
    select 1 from public.institute_portal_links l
    where l.institute_id = _institute_id
      and l.user_id = target_user_id
      and (l.student_record_id <> _student_record_id or l.relationship <> 'student')
  ) then
    raise exception 'A student account can be linked to only one student profile. Use Parent or Guardian for multiple children.';
  end if;

  if rel in ('parent','guardian') and exists (
    select 1 from public.institute_portal_links l
    where l.institute_id = _institute_id
      and l.user_id = target_user_id
      and l.relationship = 'student'
  ) then
    raise exception 'This account already has a Student link. A Student account cannot also be used as a Parent or Guardian account.';
  end if;

  insert into public.institute_portal_links(
    institute_id, student_record_id, user_id, relationship, created_by
  )
  values (_institute_id, _student_record_id, target_user_id, rel, (select auth.uid()))
  on conflict (institute_id, student_record_id, user_id)
  do update set relationship = excluded.relationship
  returning id into link_id;

  return link_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_remove_coachingos_member(_institute_id uuid, _user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
                                                                                                                                                                                                                                                                                                                                                                                                                 declare
                                                                                                                                                                                                                                                                                                                                                                                                                   caller_role text;
                                                                                                                                                                                                                                                                                                                                                                                                                     target_role text;
                                                                                                                                                                                                                                                                                                                                                                                                                     begin
                                                                                                                                                                                                                                                                                                                                                                                                                       select m.role into caller_role
                                                                                                                                                                                                                                                                                                                                                                                                                         from public.institute_members m
                                                                                                                                                                                                                                                                                                                                                                                                                           where m.institute_id = _institute_id and m.user_id = (select auth.uid());

                                                                                                                                                                                                                                                                                                                                                                                                                             if coalesce(caller_role,'') not in ('owner','admin') then
                                                                                                                                                                                                                                                                                                                                                                                                                                 raise exception 'Only institute owner or admin can remove staff'
                                                                                                                                                                                                                                                                                                                                                                                                                                       using errcode = '42501';
                                                                                                                                                                                                                                                                                                                                                                                                                                         end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                           select m.role into target_role
                                                                                                                                                                                                                                                                                                                                                                                                                                             from public.institute_members m
                                                                                                                                                                                                                                                                                                                                                                                                                                               where m.institute_id = _institute_id and m.user_id = _user_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                 if target_role is null then raise exception 'Member not found'; end if;
                                                                                                                                                                                                                                                                                                                                                                                                                                                   if target_role = 'owner' then raise exception 'The owner cannot be removed'; end if;
                                                                                                                                                                                                                                                                                                                                                                                                                                                     if caller_role = 'admin' and target_role = 'admin' then
                                                                                                                                                                                                                                                                                                                                                                                                                                                         raise exception 'Admins cannot remove another admin'
                                                                                                                                                                                                                                                                                                                                                                                                                                                               using errcode = '42501';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                   delete from public.institute_members
                                                                                                                                                                                                                                                                                                                                                                                                                                                                     where institute_id = _institute_id and user_id = _user_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                       return true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                       end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                       $function$

CREATE OR REPLACE FUNCTION public.admin_set_coachingos_institute_status(_institute_id uuid, _status text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
                                          begin
                                            if not exists (
                                                select 1 from public.platform_admins p
                                                    where p.user_id = (select auth.uid())
                                                      ) then
                                                          raise exception 'Platform Super Admin access required'
                                                                using errcode = '42501';
                                                                  end if;

                                                                    if _status not in ('pending','active','suspended') then
                                                                        raise exception 'Invalid institute status';
                                                                          end if;

                                                                            update public.institutes
                                                                              set status = _status
                                                                                where id = _institute_id;

                                                                                  if not found then
                                                                                      raise exception 'Institute not found';
                                                                                        end if;
                                                                                          return true;
                                                                                          end;
                                                                                          $function$

CREATE OR REPLACE FUNCTION public.admin_update_coachingos_member_role(_institute_id uuid, _user_id uuid, _role text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
                                                                                                                                                                                                                                                                                                                                           declare
                                                                                                                                                                                                                                                                                                                                             caller_role text;
                                                                                                                                                                                                                                                                                                                                               target_role text;
                                                                                                                                                                                                                                                                                                                                                 new_role text := lower(trim(_role));
                                                                                                                                                                                                                                                                                                                                                 begin
                                                                                                                                                                                                                                                                                                                                                   select m.role into caller_role
                                                                                                                                                                                                                                                                                                                                                     from public.institute_members m
                                                                                                                                                                                                                                                                                                                                                       where m.institute_id = _institute_id and m.user_id = (select auth.uid());

                                                                                                                                                                                                                                                                                                                                                         if coalesce(caller_role,'') not in ('owner','admin') then
                                                                                                                                                                                                                                                                                                                                                             raise exception 'Only institute owner or admin can change staff roles'
                                                                                                                                                                                                                                                                                                                                                                   using errcode = '42501';
                                                                                                                                                                                                                                                                                                                                                                     end if;
                                                                                                                                                                                                                                                                                                                                                                       if new_role not in ('admin','manager','teacher','accountant','receptionist','staff') then
                                                                                                                                                                                                                                                                                                                                                                           raise exception 'Invalid staff role';
                                                                                                                                                                                                                                                                                                                                                                             end if;

                                                                                                                                                                                                                                                                                                                                                                               select m.role into target_role
                                                                                                                                                                                                                                                                                                                                                                                 from public.institute_members m
                                                                                                                                                                                                                                                                                                                                                                                   where m.institute_id = _institute_id and m.user_id = _user_id;

                                                                                                                                                                                                                                                                                                                                                                                     if target_role is null then raise exception 'Member not found'; end if;
                                                                                                                                                                                                                                                                                                                                                                                       if target_role = 'owner' then raise exception 'The owner role cannot be changed'; end if;
                                                                                                                                                                                                                                                                                                                                                                                         if caller_role = 'admin' and (target_role = 'admin' or new_role = 'admin') then
                                                                                                                                                                                                                                                                                                                                                                                             raise exception 'Admins cannot change admin-level memberships'
                                                                                                                                                                                                                                                                                                                                                                                                   using errcode = '42501';
                                                                                                                                                                                                                                                                                                                                                                                                     end if;

                                                                                                                                                                                                                                                                                                                                                                                                       update public.institute_members
                                                                                                                                                                                                                                                                                                                                                                                                         set role = new_role
                                                                                                                                                                                                                                                                                                                                                                                                           where institute_id = _institute_id and user_id = _user_id;
                                                                                                                                                                                                                                                                                                                                                                                                             return true;
                                                                                                                                                                                                                                                                                                                                                                                                             end;
                                                                                                                                                                                                                                                                                                                                                                                                             $function$

CREATE OR REPLACE FUNCTION public.capture_coachingos_staff_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  event_title text;
  event_message text;
  target_user uuid;
  event_category text := 'staff';
  inst_id uuid;
  actor uuid := auth.uid();
begin
  if tg_table_name = 'institute_members' then
    if tg_op = 'DELETE' then
      inst_id := old.institute_id;
    else
      inst_id := new.institute_id;
    end if;
    if tg_op = 'INSERT' then
      target_user := new.user_id;
      event_title := 'Staff member added';
      event_message := 'You have been added to an institute with role: ' || coalesce(new.role,'staff') || '.';
      if target_user is not null and target_user is distinct from actor then
        insert into public.institute_notifications(institute_id,recipient_user_id,actor_user_id,category,title,message,entity_id)
        values(inst_id,target_user,actor,'staff',event_title,event_message,new.id);
      end if;
      return new;
    elsif tg_op = 'UPDATE' then
      if old.role is distinct from new.role then
        target_user := new.user_id;
        event_title := 'Your staff role was changed';
        event_message := 'Your institute role is now: ' || coalesce(new.role,'staff') || '.';
        if target_user is not null and target_user is distinct from actor then
          insert into public.institute_notifications(institute_id,recipient_user_id,actor_user_id,category,title,message,entity_id)
          values(inst_id,target_user,actor,'staff',event_title,event_message,new.id);
        end if;
      end if;
      return new;
    elsif tg_op = 'DELETE' then
      target_user := old.user_id;
      if target_user is not null and target_user is distinct from actor then
        insert into public.institute_notifications(institute_id,recipient_user_id,actor_user_id,category,title,message,entity_id)
        values(inst_id,target_user,actor,'staff','Institute access removed','Your access to this institute has been removed.',old.id);
      end if;
      return old;
    end if;
  elsif tg_table_name = 'institute_staff_invitations' then
    inst_id := new.institute_id;
    if tg_op = 'INSERT' then
      insert into public.institute_notifications(institute_id,recipient_user_id,actor_user_id,category,title,message,entity_id)
      select inst_id, m.user_id, actor, 'invitation', 'A staff invitation was created',
        'A new invitation was created for ' || coalesce(new.email,new.phone,'a staff member') || '.',
        new.id
      from public.institute_members m
      where m.institute_id = inst_id
        and m.role in ('owner','admin','manager')
        and m.user_id is distinct from actor;
      return new;
    elsif tg_op = 'UPDATE' and old.status is distinct from new.status then
      if new.status = 'accepted' and new.created_by is not null and new.created_by is distinct from new.accepted_by then
        insert into public.institute_notifications(institute_id,recipient_user_id,actor_user_id,category,title,message,entity_id)
        values(inst_id,new.created_by,new.accepted_by,'invitation','Staff invitation accepted',
          'The invitation for ' || coalesce(new.email,new.phone,'a staff member') || ' was accepted.',new.id);
      elsif new.status = 'revoked' then
        for target_user in
          select u.id
          from auth.users u
          where (new.email is not null and lower(u.email) = lower(new.email) and u.email_confirmed_at is not null)
             or (new.phone is not null and u.phone = new.phone and u.phone_confirmed_at is not null)
        loop
          if target_user is distinct from actor then
            insert into public.institute_notifications(institute_id,recipient_user_id,actor_user_id,category,title,message,entity_id)
            values(inst_id,target_user,actor,'invitation','Staff invitation revoked',
              'A staff invitation for your account was revoked.',new.id);
          end if;
        end loop;
      end if;
      return new;
    end if;
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_coachingos_subscription_limits()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_plan public.subscription_plans%rowtype;
  v_count bigint;
begin
  if not public.coachingos_subscription_write_allowed(new.institute_id) then
    raise exception 'Subscription is expired or inactive. Contact the platform administrator.'
      using errcode = '42501';
  end if;

  if tg_table_name = 'coachingos_records' then
    select p.* into v_plan
    from public.institute_subscriptions s
    join public.subscription_plans p on p.id = s.plan_id
    where s.institute_id = new.institute_id
    limit 1;
    if not found then return new; end if;

    if tg_op = 'UPDATE'
       and old.institute_id = new.institute_id
       and old.record_type = new.record_type then
      return new;
    end if;

    perform pg_advisory_xact_lock(hashtextextended(new.institute_id::text, 0));

    if v_plan.max_records is not null then
      select count(*) into v_count
      from public.coachingos_records r
      where r.institute_id = new.institute_id;
      if v_count >= v_plan.max_records then
        raise exception 'Plan record limit reached (%). Upgrade the plan to add more records.', v_plan.max_records
          using errcode = 'P0001';
      end if;
    end if;

    if new.record_type = 'branches' and v_plan.max_branches is not null then
      select count(*) into v_count
      from public.coachingos_records r
      where r.institute_id = new.institute_id
        and r.record_type = 'branches';
      if v_count >= v_plan.max_branches then
        raise exception 'Plan branch limit reached (%). Upgrade the plan to add another branch.', v_plan.max_branches
          using errcode = 'P0001';
      end if;
    end if;
    return new;

  elsif tg_table_name = 'institute_members' then
    if tg_op = 'UPDATE' and old.institute_id = new.institute_id then
      return new;
    end if;

    select p.* into v_plan
    from public.institute_subscriptions s
    join public.subscription_plans p on p.id = s.plan_id
    where s.institute_id = new.institute_id
    limit 1;
    if not found then return new; end if;

    perform pg_advisory_xact_lock(hashtextextended(new.institute_id::text, 0));

    if v_plan.max_members is not null then
      select count(*) into v_count
      from public.institute_members m
      where m.institute_id = new.institute_id;
      if v_count >= v_plan.max_members then
        raise exception 'Plan member limit reached (%). Upgrade the plan to add another member.', v_plan.max_members
          using errcode = 'P0001';
      end if;
    end if;
    return new;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_guardian_attendance_delivery()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  student_id uuid;
  student_data jsonb;
  guardian_phone text;
  consent text;
  event_token text;
  sms_status text;
begin
  if new.record_type <> 'attendance'
     or coalesce(new.record_data->>'status','') <> 'Present' then
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if old.record_type = 'attendance'
       and coalesce(old.record_data->>'status','') = 'Present' then
      return new;
    end if;
  end if;

  student_id := nullif(new.record_data->>'student_record_id','')::uuid;
  event_token := new.id::text || ':' || coalesce(new.updated_at, new.created_at, pg_catalog.now())::text;

  if student_id is not null then
    select s.record_data into student_data
    from public.coachingos_records s
    where s.id = student_id
      and s.institute_id = new.institute_id
      and s.record_type = 'students'
    limit 1;
  end if;

  guardian_phone := nullif(pg_catalog.btrim(coalesce(student_data->>'guardian_phone','')), '');
  consent := lower(pg_catalog.btrim(coalesce(student_data->>'guardian_report_consent','')));

  sms_status := case
    when student_data is null then 'blocked'
    when consent <> 'yes' then 'skipped_consent'
    when guardian_phone is null then 'skipped_no_contact'
    else 'queued'
  end;

  -- Email notifications are intentionally disabled until the institute configures
  -- and verifies an email provider/domain. Keep an audit row without queueing email.
  insert into public.guardian_delivery_logs(
    institute_id, attendance_record_id, student_record_id, event_key,
    channel, recipient_masked, status, error_message
  ) values
  (
    new.institute_id, new.id, student_id, event_token, 'email',
    null, 'blocked', 'email_notifications_disabled'
  ),
  (
    new.institute_id, new.id, student_id, event_token, 'sms',
    case when guardian_phone is null then null
      else '***'||pg_catalog.right(regexp_replace(guardian_phone,'[^0-9]','','g'),4) end,
    sms_status,
    case when student_data is null then 'student_record_not_found'
      when consent <> 'yes' then 'guardian_consent_not_yes'
      when guardian_phone is null then 'guardian_phone_missing'
      else null end
  )
  on conflict (event_key,channel) do nothing;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_coachingos_unread_notification_count(_institute_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.institute_members m
    join public.institutes i on i.id = m.institute_id
    where m.institute_id = _institute_id
      and m.user_id = (select auth.uid())
      and i.status = 'active'
  ) then
    raise exception 'Active institute membership required' using errcode = '42501';
  end if;

  return (
    select count(*)::integer
    from public.institute_notifications n
    where n.institute_id = _institute_id
      and n.recipient_user_id = (select auth.uid())
      and n.read_at is null
  );
end;
$function$

