CREATE OR REPLACE FUNCTION public.retry_coachingos_guardian_delivery(_log_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_institute uuid;
  target_attendance uuid;
  caller_role text;
begin
  select l.institute_id into target_institute
  from public.guardian_delivery_logs l
  where l.id = _log_id and l.channel = 'sms';

  if target_institute is null then raise exception 'SMS delivery log not found'; end if;

  select m.role into caller_role
  from public.institute_members m
  where m.institute_id = target_institute
    and m.user_id = (select auth.uid())
  limit 1;

  if coalesce(caller_role,'') not in ('owner','admin','manager','receptionist') then
    raise exception 'Not authorized to retry guardian delivery'
      using errcode = '42501';
  end if;

  update public.guardian_delivery_logs l
  set status = 'queued',
      next_attempt_at = pg_catalog.now(),
      processing_started_at = null,
      error_message = null,
      updated_at = pg_catalog.now()
  where l.id = _log_id
    and l.channel = 'sms'
    and l.status in ('failed','blocked')
    and l.attempt_count < 3
  returning l.attendance_record_id into target_attendance;

  if target_attendance is null then
    raise exception 'SMS delivery is not retryable or retry limit reached';
  end if;
  return target_attendance;
end;
$function$
